-- Fiche Les nombres (CE1) - anglais, notion 'en_nombres'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'ce1', 'english', 'Les nombres', $fiche$
[titre]Les nombres jusqu'à 31[/titre]
[cadre]De 13 à 19 : [b]-teen[/b] → thir[b][color=#C62828]teen[/color][/b], four[b][color=#C62828]teen[/color][/b], fif[b][color=#C62828]teen[/color][/b].
Les dizaines : [b]-ty[/b] → twen[b][color=#C62828]ty[/color][/b], thir[b][color=#C62828]ty[/color][/b].
21 = twenty[b][color=#C62828]-[/color][/b]one : un [b]tiret[/b] entre les deux.[/cadre]
[cadre=astuce]11 = eleven et 12 = twelve sont à apprendre par cœur.[/cadre]
